/* Mututsva FSMS client for the shared SQLite station application. */
const STORE_KEY = 'mututsva-fsms-v1';
let currencyCode='USD';
const currency={format(value){try{return new Intl.NumberFormat('en-US',{style:'currency',currency:currencyCode,maximumFractionDigits:2}).format(value)}catch{return `${currencyCode} ${Number(value).toFixed(2)}`}}};
const number = new Intl.NumberFormat('en-US',{maximumFractionDigits:1});
const localDateISO = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const todayISO = () => localDateISO(new Date());
const dayOffset = n => {const d=new Date();d.setDate(d.getDate()+n);return localDateISO(d)};
const uid = () => `${Date.now().toString(36)}${Math.random().toString(36).slice(2,6)}`;
const initialState = () => ({
  settings:{station:'Mututsva Station',currency:'USD',tolerance:150},
  fuel:[{id:'petrol',name:'Petrol',price:1.48,stock:12840,capacity:20000,color:'#4b966b'},{id:'diesel',name:'Diesel',price:1.52,stock:8640,capacity:15000,color:'#d1a04a'},{id:'blend',name:'Blend',price:1.42,stock:3260,capacity:8000,color:'#7398a0'}],
  suppliers:['Petrotrade','No. 1 Fuel','Puma Energy'],
  deliveries:[{id:'DL-2408',supplier:'Petrotrade',fuel:'petrol',quantity:5000,cost:1.19,date:dayOffset(-1),invoice:'PT-19482',status:'Pending',created:'Yesterday'}],
  measurements:[{id:'TM-109',fuel:'petrol',quantity:12790,date:dayOffset(0),time:'07:30',note:'Morning dip reading',variance:50}],
  sales:[
    {id:'TX-8431',fuel:'petrol',litres:32.4,price:1.48,method:'Cash',customer:'Walk-in',pump:'Pump 1',date:todayISO(),time:'09:42'},
    {id:'TX-8430',fuel:'diesel',litres:48,price:1.52,method:'Bank card',customer:'Walk-in',pump:'Pump 3',date:todayISO(),time:'09:18'},
    {id:'TX-8429',fuel:'petrol',litres:25,price:1.48,method:'Mobile money',customer:'Walk-in',pump:'Pump 2',date:todayISO(),time:'08:56'},
    {id:'TX-8428',fuel:'blend',litres:20,price:1.42,method:'Cash',customer:'Walk-in',pump:'Pump 4',date:todayISO(),time:'08:12'},
    {id:'TX-8427',fuel:'diesel',litres:55,price:1.52,method:'Bank card',customer:'Walk-in',pump:'Pump 3',date:dayOffset(-1),time:'17:44'}
  ],
  shifts:[{id:'SH-061',attendant:'Tendai Mupfumi',pump:'Pump 1',fuel:'petrol',opening:25120,closing:null,status:'Open',date:todayISO(),opened:'06:00',collections:{},note:''},{id:'SH-060',attendant:'Nyasha Dube',pump:'Pump 2',fuel:'petrol',opening:48620,closing:49052,status:'Closed',date:dayOffset(-1),opened:'06:00',closed:'14:00',collections:{Cash:420,'Bank card':300,'Mobile money':160},note:'Short collection explained by fleet credit'}],
  expenses:[{id:'EX-201',description:'Generator servicing',category:'Maintenance',amount:85,date:dayOffset(-1),status:'Recorded'}],
  adjustments:[],audit:[{text:'Shift SH-061 opened by Tariro Moyo',time:'Today, 06:00',icon:'◷'},{text:'Tank measurement recorded for Petrol',time:'Today, 07:30',icon:'◫'},{text:'Sale TX-8431 recorded · Cash',time:'Today, 09:42',icon:'▤'}]
});
let state=null;
let currentUser=null;
let currentView='dashboard';
const views={dashboard:'Overview',sales:'Point of sale',deliveries:'Deliveries',inventory:'Fuel inventory',shifts:'Shifts & pumps',reconciliation:'Reconciliation',finance:'Finance',reports:'Reports',settings:'Station settings'};
const $=s=>document.querySelector(s); const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fuelBy=id=>state.fuel.find(x=>x.id===id); const fuelName=id=>fuelBy(id)?.name||id;
const save=()=>{};
const addAudit=(text,icon='•')=>{const d=new Date();state.audit.unshift({text,time:`Today, ${d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`,icon});state.audit=state.audit.slice(0,20)};
const amountOf=s=>s.litres*s.price;
const salesToday=()=>state.sales.filter(s=>s.date===todayISO()&&!s.reversedAt);
let reportDate=todayISO();const reportSales=()=>state.sales.filter(s=>s.date===reportDate&&!s.reversedAt);const accountBalance=c=>state.sales.filter(s=>s.method==='Customer credit'&&s.customerId===c.id&&!s.reversedAt).reduce((a,s)=>a+amountOf(s),0)-state.repayments.filter(r=>r.customerId===c.id).reduce((a,r)=>a+r.amount,0);
const totalSales=rows=>rows.filter(s=>!s.reversedAt).reduce((a,s)=>a+amountOf(s),0);
const shiftLitres=s=>Math.max(0,(s.closing??s.opening)-s.opening);
const expectedStock=f=>f.stock;
const status=(v)=>`<span class="status ${String(v).toLowerCase()}">${esc(v)}</span>`;
const btn=(label,action,primary=true)=>`<button class="button ${primary?'primary':'secondary'}" data-action="${action}">${primary?'<span class="plus">+</span>':''}${label}</button>`;
const fuelOptions=selected=>state.fuel.map(f=>`<option value="${f.id}" ${f.id===selected?'selected':''}>${esc(f.name)}</option>`).join('');
const methodOptions=['Cash','Bank card','Mobile money','Bank transfer','Customer credit'].map(x=>`<option>${x}</option>`).join('');
function header(title,description,action=''){const dateLabel=new Date().toLocaleDateString('en',{weekday:'long'}).toUpperCase();return `<div class="page-heading"><div><span class="eyebrow">${currentView==='dashboard'?`${dateLabel} · STATION OPERATIONS`:'STATION OPERATIONS'}</span><h1>${title}</h1><p>${description}</p></div>${action}</div>`}
function chart(){const dates=Array.from({length:7},(_,i)=>{const d=new Date(`${dayOffset(i-6)}T12:00:00`);return {iso:dayOffset(i-6),label:d.toLocaleDateString('en',{weekday:'short'})}});const values=dates.map(d=>state.sales.filter(s=>s.date===d.iso&&!s.reversedAt).reduce((a,s)=>a+amountOf(s),0)),max=Math.max(1,...values);const w=600,h=190,pad=18;const pts=values.map((v,i)=>`${pad+i*(w-2*pad)/(values.length-1)},${h-22-(v/max*120)}`).join(' ');return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Recorded sales values for the last seven days"><defs><linearGradient id="chartFade" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#7db18b" stop-opacity=".24"/><stop offset="100%" stop-color="#7db18b" stop-opacity="0"/></linearGradient></defs>${[30,70,110,150].map(y=>`<line class="chart-grid" x1="${pad}" x2="${w-pad}" y1="${y}" y2="${y}"/>`).join('')}<polygon class="chart-fill" points="${pad},${h-22} ${pts} ${w-pad},${h-22}"/><polyline class="chart-line" points="${pts}"/>${dates.map((d,i)=>`<text class="chart-label" x="${pad+i*(w-2*pad)/6}" y="${h-3}" text-anchor="middle">${d.label}</text>`).join('')}</svg>`}
function renderDashboard(){const today=salesToday(),revenue=totalSales(today),litres=today.reduce((s,x)=>s+x.litres,0),pending=state.deliveries.filter(d=>d.status==='Pending').length;const payment=today.reduce((o,s)=>(o[s.method]=(o[s.method]||0)+amountOf(s),o),{});const fuelCards=state.fuel.map(f=>`<div class="fuel-row"><div><div class="fuel-name">${esc(f.name)}</div><div class="fuel-meta">${number.format(f.stock/f.capacity*100)}% of ${number.format(f.capacity)} L capacity</div></div><div class="fuel-qty">${number.format(f.stock)} <small>L</small></div><div class="progress-track"><div class="progress-bar ${f.stock/f.capacity<.3?'warn':''}" style="width:${Math.min(100,Math.max(1,f.stock/f.capacity*100))}%;background:${f.stock/f.capacity<.3?'':' '+f.color}"></div></div></div>`).join('');const rows=today.slice(0,4).map(s=>`<tr><td><div class="primary-cell">${s.id}</div><div class="secondary-cell">${s.time}</div></td><td>${fuelName(s.fuel)}</td><td>${number.format(s.litres)} L</td><td>${s.method}</td><td class="primary-cell">${currency.format(amountOf(s))}</td></tr>`).join('')||'<tr><td colspan="5" class="empty-state">No sales recorded for today.</td></tr>';return `${header(`Good morning, ${esc(currentUser.name.split(/\s+/)[0])}`,'Here is what is happening at your station today.',btn('New sale','new-sale'))}<div class="stats-grid"><div class="stat-card"><div class="stat-top">Sales today <span class="stat-icon">＄</span></div><div class="stat-value">${currency.format(revenue)}</div><div class="stat-foot"><span class="positive">${today.length} transactions</span> recorded today</div></div><div class="stat-card"><div class="stat-top">Volume sold (POS) <span class="stat-icon">◉</span></div><div class="stat-value">${number.format(litres)} <small style="font:500 12px 'DM Sans';color:#718078">L</small></div><div class="stat-foot">POS sales volume; pump meter totals are separate</div></div><div class="stat-card"><div class="stat-top">Available stock <span class="stat-icon">◫</span></div><div class="stat-value">${number.format(state.fuel.reduce((a,f)=>a+f.stock,0))} <small style="font:500 12px 'DM Sans';color:#718078">L</small></div><div class="stat-foot">Across ${state.fuel.length} fuel products</div></div><div class="stat-card"><div class="stat-top">To review <span class="stat-icon">◷</span></div><div class="stat-value">${pending+state.shifts.filter(s=>s.status==='Pending review').length}</div><div class="stat-foot">${pending} ${pending===1?'delivery':'deliveries'} awaiting approval</div></div></div><div class="overview-grid"><section class="panel"><div class="panel-head"><div><h2>Sales activity</h2><p>Recorded transaction value · last 7 days</p></div><div class="chart-legend"><span><i class="legend-dot"></i>Sales</span></div></div><div class="chart-wrap">${chart()}</div></section><section class="panel"><div class="panel-head"><div><h2>Fuel availability</h2><p>Calculated stock by product</p></div><a class="text-link" data-view="inventory">View tanks →</a></div><div class="fuel-list">${fuelCards}</div></section></div><div class="two-panels"><section class="panel table-panel"><div class="panel-head"><div><h2>Recent sales</h2><p>Latest point-of-sale transactions</p></div><a class="text-link" data-view="sales">All transactions →</a></div><div class="table-wrap"><table><thead><tr><th>Transaction</th><th>Fuel</th><th>Volume</th><th>Payment</th><th>Total</th></tr></thead><tbody>${rows}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>Activity log</h2><p>Recent station updates</p></div><span class="eyebrow">LATEST</span></div><div class="activity-list">${state.audit.slice(0,4).map(a=>`<div class="activity"><span class="activity-dot">${a.icon}</span><div><p>${esc(a.text)}</p><small>${esc(a.time)}</small></div></div>`).join('')}</div></section></div>`}
function renderSales(){const rows=[...state.sales].sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time)).map(s=>`<tr><td><div class="primary-cell">${s.id}</div><div class="secondary-cell">${s.date} · ${s.time}</div></td><td>${fuelName(s.fuel)}</td><td>${number.format(s.litres)} L</td><td>${currency.format(s.price)}/L</td><td>${s.pump}</td><td>${s.method}</td><td class="primary-cell">${currency.format(amountOf(s))}</td><td>${s.reversedAt?status('Reversed'):state.saleReversals?.some(r=>r.saleId===s.id&&r.status==='Pending')?status('Pending review'):(currentUser.role==='System Administrator'||currentUser.role==='Station Manager'||currentUser.role==='Supervisor'||currentUser.role==='Cashier'?`<button class="inline-action" data-action="request-reversal" data-id="${s.id}">Request reversal</button>`:'?')}</td></tr>`).join('')||'<tr><td colspan="8" class="empty-state">No sales yet. Record the first transaction.</td></tr>';return `${header('Point of sale','Record fuel transactions and the payment collected.',btn('Record a sale','new-sale'))}<div class="section-note"><strong>Sales and pump totals are separate records.</strong> Record what was sold and how it was paid; shift reconciliation compares these records with meter readings.</div><div class="stats-grid"><div class="stat-card"><div class="stat-top">Today's sales <span class="stat-icon">＄</span></div><div class="stat-value">${currency.format(totalSales(salesToday()))}</div><div class="stat-foot">${salesToday().length} transactions</div></div><div class="stat-card"><div class="stat-top">Litres sold <span class="stat-icon">◉</span></div><div class="stat-value">${number.format(salesToday().reduce((a,s)=>a+s.litres,0))} L</div><div class="stat-foot">Calculated from POS sales</div></div><div class="stat-card"><div class="stat-top">Cash collected <span class="stat-icon">＄</span></div><div class="stat-value">${currency.format(salesToday().filter(s=>s.method==='Cash').reduce((a,s)=>a+amountOf(s),0))}</div><div class="stat-foot">Sales value, by payment method</div></div><div class="stat-card"><div class="stat-top">Customer credit <span class="stat-icon">↗</span></div><div class="stat-value">${currency.format(salesToday().filter(s=>s.method==='Customer credit').reduce((a,s)=>a+amountOf(s),0))}</div><div class="stat-foot">Credit sales recorded today</div></div></div><section class="panel table-panel"><div class="panel-head"><div><h2>Transactions</h2><p>Historical selling price is saved with each sale</p></div><span class="eyebrow">${state.sales.length} RECORDS</span></div><div class="filter-row" style="padding:0 18px"><input id="sales-search" placeholder="Search transaction or pump…" aria-label="Search sales"><select id="sales-filter"><option value="">All payment methods</option>${methodOptions}</select><span class="filter-spacer"></span><button class="button secondary" data-action="export-sales">Export CSV</button></div><div class="table-wrap"><table><thead><tr><th>Transaction</th><th>Product</th><th>Volume</th><th>Unit price</th><th>Pump</th><th>Payment</th><th>Total</th><th>Status / action</th></tr></thead><tbody id="sales-body">${rows}</tbody></table></div></section>`}
function renderDeliveries(){const pending=state.deliveries.filter(d=>d.status==='Pending').length,orderRows=[...(state.purchaseOrders||[])].sort((x,y)=>y.date.localeCompare(x.date)).map(o=>`<tr><td><div class="primary-cell">${o.id}</div><div class="secondary-cell">${o.date}</div></td><td>${esc(o.supplier)}</td><td>${fuelName(o.fuel)}</td><td>${number.format(o.quantity)} L</td><td>${number.format(o.received||0)} / ${number.format(o.quantity)} L</td><td>${currency.format(o.cost)}/L</td><td>${status(o.status)}</td><td>${o.status==='Pending approval'?`<button class="inline-action" data-action="review-order" data-id="${o.id}">Review</button>`:'?'}</td></tr>`).join('')||'<tr><td colspan="8" class="empty-state">No purchase orders recorded yet.</td></tr>',rows=[...state.deliveries].sort((x,y)=>y.date.localeCompare(x.date)).map(d=>`<tr><td><div class="primary-cell">${d.id}</div><div class="secondary-cell">${d.date}</div></td><td>${esc(d.orderId||'?')}</td><td>${esc(d.supplier)}</td><td>${fuelName(d.fuel)}</td><td>${number.format(d.quantity)} L</td><td>${currency.format(d.cost)}/L</td><td>${esc(d.invoice||'?')}</td><td>${status(d.status)}</td><td>${d.status==='Pending'?`<button class="inline-action" data-action="approve-delivery" data-id="${d.id}">Review & approve</button>`:'?'}</td></tr>`).join('')||'<tr><td colspan="9" class="empty-state">No deliveries recorded yet.</td></tr>';return `${header('Deliveries','Approve purchase orders first, then verify each receipt before stock is posted.',btn('Create purchase order','new-order'))}<div class="section-note"><strong>${pending} delivery${pending===1?'':'ies'} awaiting review.</strong> Only manager-approved deliveries matching an approved purchase order can post to stock. Partial receipts are tracked.</div><div class="filter-row"><button class="button secondary" data-action="new-delivery">Record delivery against order</button><span class="filter-spacer"></span></div><section class="panel table-panel"><div class="panel-head"><div><h2>Purchase orders</h2><p>Supplier commitments and approval/receipt tracking</p></div></div><div class="table-wrap"><table><thead><tr><th>Order</th><th>Supplier</th><th>Fuel</th><th>Ordered</th><th>Received</th><th>Agreed cost</th><th>Status</th><th>Action</th></tr></thead><tbody>${orderRows}</tbody></table></div></section><section class="panel table-panel" style="margin-top:15px"><div class="panel-head"><div><h2>Supplier deliveries</h2><p>Receipt records linked to an approved order</p></div></div><div class="table-wrap"><table><thead><tr><th>Delivery</th><th>Order</th><th>Supplier</th><th>Fuel</th><th>Quantity</th><th>Cost</th><th>Invoice</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows}</tbody></table></div></section>`}
function renderInventory(){const cards=state.fuel.map(f=>{const measured=state.measurements.filter(m=>m.fuel===f.id).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time))[0];const variance=measured?f.stock-measured.quantity:null;return `<section class="panel"><div class="panel-head"><div><h2>${esc(f.name)}</h2><p>Storage tank · ${number.format(f.capacity)} L capacity</p></div><span class="stat-icon">◫</span></div><div class="metric-pair"><div class="metric-box"><small>Calculated stock</small><b>${number.format(f.stock)} L</b></div><div class="metric-box"><small>Latest physical dip</small><b>${measured?number.format(measured.quantity)+' L':'Not recorded'}</b></div></div><div class="progress-track" style="height:7px"><div class="progress-bar" style="width:${Math.min(100,f.stock/f.capacity*100)}%;background:${f.color}"></div></div><p class="fuel-meta" style="margin:8px 0 0">${measured?`Measured ${measured.date} · Variance ${variance>=0?'+':''}${number.format(variance)} L${Math.abs(variance)>state.settings.tolerance?' · Investigation required':''}`:'Record a tank dip to compare physical and calculated stock.'}</p></section>`}).join('');const rows=[...state.measurements].sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time)).map(m=>`<tr><td>${m.date} · ${m.time}</td><td>${fuelName(m.fuel)}</td><td>${number.format(expectedStock(fuelBy(m.fuel)))} L</td><td>${number.format(m.quantity)} L</td><td>${m.variance>=0?'+':''}${number.format(m.variance)} L</td><td>${Math.abs(m.variance)>state.settings.tolerance?status('Investigate'):status('Within tolerance')}</td><td>${esc(m.note||'—')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty-state">No tank measurements recorded yet.</td></tr>';return `${header('Fuel inventory','Calculated balances and physical tank measurements stay distinct.',btn('Record tank dip','new-measurement'))}<div class="section-note"><strong>Calculated stock</strong> = opening balance + approved deliveries − POS fuel sales + approved adjustments. A tank dip records a physical measurement; it does not silently rewrite the calculated balance.</div><div class="settings-grid">${cards}</div><section class="panel table-panel" style="margin-top:15px"><div class="panel-head"><div><h2>Tank measurement history</h2><p>Differences outside the configured tolerance are flagged for investigation.</p></div><button class="button secondary" data-action="new-adjustment">+ Request adjustment</button></div><div class="table-wrap"><table><thead><tr><th>Recorded</th><th>Product</th><th>Calculated</th><th>Measured</th><th>Variance</th><th>Review</th><th>Note</th></tr></thead><tbody>${rows}</tbody></table></div></section><section class="panel table-panel" style="margin-top:15px"><div class="panel-head"><div><h2>Stock adjustments</h2><p>Authorised adjustments are separately recorded</p></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Product</th><th>Change</th><th>Reason</th><th>Status</th></tr></thead><tbody>${state.adjustments.map(a=>`<tr><td>${a.date}</td><td>${fuelName(a.fuel)}</td><td>${a.quantity>=0?'+':''}${number.format(a.quantity)} L</td><td>${esc(a.reason)}</td><td>${a.status==='Pending'?`${status(a.status)} <button class="inline-action" data-action="approve-adjustment" data-id="${a.id}">Approve</button>`:status(a.status)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty-state">No adjustment records.</td></tr>'}</tbody></table></div></section><section class="panel table-panel" style="margin-top:15px"><div class="panel-head"><div><h2>Stock movement ledger</h2><p>Every posted delivery, POS sale, approved adjustment and reversal is retained.</p></div></div><div class="table-wrap"><table><thead><tr><th>Recorded</th><th>Movement</th><th>Reference</th><th>Change</th><th>Balance after</th><th>Recorded by</th></tr></thead><tbody>${(state.stockLedger||[]).sort((a,b)=>b.recordedAt.localeCompare(a.recordedAt)).map(x=>`<tr><td>${new Date(x.recordedAt).toLocaleString()}</td><td>${esc(x.kind)}</td><td>${esc(x.reference)}</td><td>${x.delta>=0?'+':''}${number.format(x.delta)} L</td><td>${number.format(x.after)} L</td><td>${esc(x.recordedBy)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty-state">No posted movements recorded yet.</td></tr>'}</tbody></table></div></section>`}
function renderShifts(){const rows=[...state.shifts].sort((a,b)=>(b.date+b.opened).localeCompare(a.date+a.opened)).map(s=>`<tr><td><div class="primary-cell">${s.id}</div><div class="secondary-cell">${s.date} · ${s.opened}</div></td><td>${esc(s.attendant)}</td><td>${s.pump}</td><td>${fuelName(s.fuel)}</td><td>${number.format(s.opening)} L</td><td>${s.closing==null?'—':number.format(s.closing)+' L'}</td><td>${s.closing==null?'—':number.format(shiftLitres(s))+' L'}</td><td>${status(s.status)}</td><td>${s.status==='Open'?`<button class="inline-action" data-action="close-shift" data-id="${s.id}">Close shift</button>`:s.status==='Pending review'?`<button class="inline-action" data-action="review-shift" data-id="${s.id}">Review</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="9" class="empty-state">No shifts recorded yet.</td></tr>';return `${header('Shifts & pumps','Assign attendants, capture meter readings and close shifts.',btn('Open a shift','new-shift'))}<div class="section-note"><strong>Manual meter entry is active.</strong> Dispensed volume is calculated from closing minus opening meter readings. Meter totals and POS sales are stored separately for reconciliation.</div><div class="stats-grid"><div class="stat-card"><div class="stat-top">Open shifts <span class="stat-icon">◷</span></div><div class="stat-value">${state.shifts.filter(s=>s.status==='Open').length}</div><div class="stat-foot">Currently active assignments</div></div><div class="stat-card"><div class="stat-top">Today's recorded dispensing <span class="stat-icon">◉</span></div><div class="stat-value">${number.format(state.shifts.filter(s=>s.date===todayISO()&&s.closing!=null).reduce((a,s)=>a+shiftLitres(s),0))} L</div><div class="stat-foot">From closed meter readings</div></div><div class="stat-card"><div class="stat-top">Pending review <span class="stat-icon">◷</span></div><div class="stat-value">${state.shifts.filter(s=>s.status==='Pending review').length}</div><div class="stat-foot">Awaiting manager approval</div></div><div class="stat-card"><div class="stat-top">Active attendants <span class="stat-icon">♙</span></div><div class="stat-value">${new Set(state.shifts.filter(s=>s.status==='Open').map(s=>s.attendant)).size}</div><div class="stat-foot">Assigned to open shifts</div></div></div><section class="panel table-panel"><div class="panel-head"><div><h2>Shift register</h2><p>Readings associated with assigned attendant, pump and shift</p></div></div><div class="table-wrap"><table><thead><tr><th>Shift</th><th>Attendant</th><th>Pump</th><th>Fuel</th><th>Opening meter</th><th>Closing meter</th><th>Dispensed</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows}</tbody></table></div></section>`}
function renderReconciliation(){const closed=state.shifts.filter(s=>s.closing!=null);const items=closed.map(s=>{const expected=shiftLitres(s)*(s.price||fuelBy(s.fuel)?.price||0);const collected=Object.values(s.collections||{}).reduce((a,x)=>a+Number(x||0),0);const pos=totalSales(s.sales||[]);const variance=expected-collected;return `<tr><td><div class="primary-cell">${s.id}</div><div class="secondary-cell">${s.date} · ${esc(s.attendant)}</div></td><td>${s.pump}</td><td>${number.format(shiftLitres(s))} L</td><td>${currency.format(expected)}</td><td>${currency.format(pos)} POS</td><td>${currency.format(collected)}</td><td class="${Math.abs(variance)>1?'negative':'positive'}">${currency.format(variance)}</td><td>${s.status==='Closed'?status(Math.abs(variance)>1?'Investigate':'Approved'):status(s.status)}</td><td>${s.status==='Pending review'?`<button class="inline-action" data-action="review-shift" data-id="${s.id}">Review & close</button>`:s.status==='Closed'?'<span class="secondary-cell">Reviewed</span>':'—'}</td></tr>`}).join('')||'<tr><td colspan="9" class="empty-state">Close a shift to create its reconciliation record.</td></tr>';const reversalRows=(state.saleReversals||[]).filter(r=>r.status==='Pending').map(r=>{const sale=state.sales.find(x=>x.id===r.saleId);return sale?`<tr><td>${sale.id}</td><td>${fuelName(sale.fuel)}</td><td>${number.format(sale.litres)} L</td><td>${esc(r.reason)}</td><td>${esc(r.requestedBy)}</td><td><button class="inline-action" data-action="review-reversal" data-id="${r.id}">Review</button></td></tr>`:''}).join('')||'<tr><td colspan="6" class="empty-state">No sale reversals awaiting approval.</td></tr>';return `${header('Reconciliation','Compare meter movement with POS sales and recorded collections.') }<div class="section-note"><strong>A variance is an investigation flag, not a finding of misconduct.</strong> Meter estimates, POS transactions and collections are shown separately. Add review notes before approving a difference.</div><div class="stats-grid"><div class="stat-card"><div class="stat-top">Shifts to reconcile <span class="stat-icon">⟳</span></div><div class="stat-value">${state.shifts.filter(s=>s.status==='Pending review').length}</div><div class="stat-foot">Closed readings awaiting review</div></div><div class="stat-card"><div class="stat-top">Open investigations <span class="stat-icon">⚑</span></div><div class="stat-value">${closed.filter(s=>Math.abs(shiftLitres(s)*(s.price||fuelBy(s.fuel)?.price||0)-Object.values(s.collections||{}).reduce((a,x)=>a+Number(x||0),0))>1).length}</div><div class="stat-foot">Collection differences for review</div></div><div class="stat-card"><div class="stat-top">Tank dip tolerance <span class="stat-icon">◫</span></div><div class="stat-value">${number.format(state.settings.tolerance)} L</div><div class="stat-foot">Station configured threshold</div></div><div class="stat-card"><div class="stat-top">Pump readings <span class="stat-icon">◉</span></div><div class="stat-value">${closed.length}</div><div class="stat-foot">Closed shift records</div></div></div><section class="panel table-panel"><div class="panel-head"><div><h2>Shift reconciliation register</h2><p>Expected revenue is an estimate from meter volume × shift selling price; POS sales and collections are shown separately.</p></div></div><div class="table-wrap"><table><thead><tr><th>Shift</th><th>Pump</th><th>Dispensed</th><th>Expected sales</th><th>POS sales</th><th>Collections</th><th>Variance</th><th>Review status</th><th>Action</th></tr></thead><tbody>${items}</tbody></table></div></section><section class="panel table-panel" style="margin-top:15px"><div class="panel-head"><div><h2>Sale reversals</h2><p>Manager approval is required; original sales remain in the audit history.</p></div></div><div class="table-wrap"><table><thead><tr><th>Sale</th><th>Product</th><th>Volume</th><th>Reason</th><th>Requested by</th><th></th></tr></thead><tbody>${reversalRows}</tbody></table></div></section>`}
function renderFinance(){const rows=[...state.expenses].sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<tr><td>${e.date}</td><td class="primary-cell">${esc(e.description)}</td><td>${esc(e.category)}</td><td>${status(e.status)}</td><td class="primary-cell">${currency.format(e.amount)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty-state">No expenses recorded.</td></tr>';const sales=totalSales(salesToday()),collections=salesToday().filter(s=>s.method!=='Customer credit').reduce((a,s)=>a+amountOf(s),0),credit=salesToday().filter(s=>s.method==='Customer credit').reduce((a,s)=>a+amountOf(s),0),expenses=state.expenses.filter(e=>e.date===todayISO()).reduce((a,e)=>a+e.amount,0),customers=(state.customers||[]).map(c=>{const balance=accountBalance(c);return `<tr><td class="primary-cell">${esc(c.name)}</td><td>${esc(c.contact||'?')}</td><td>${currency.format(c.creditLimit)}</td><td>${currency.format(balance)}</td><td>${currency.format(Math.max(0,c.creditLimit-balance))}</td><td>${balance>0?`<button class="inline-action" data-action="repay-customer" data-id="${c.id}">Record repayment</button>`:'?'}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty-state">No customer credit accounts configured.</td></tr>',repayments=[...(state.repayments||[])].sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<tr><td>${r.date}</td><td>${esc(r.customer)}</td><td>${esc(r.method)}</td><td>${esc(r.reference||'?')}</td><td>${currency.format(r.amount)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty-state">No repayments recorded yet.</td></tr>';return `${header('Finance','Track sales, collections, expenses and customer account balances.',btn('Record expense','new-expense'))}<div class="section-note"><strong>Revenue, collections, credit and expenses are separate measures.</strong> Credit is only recorded against a registered account with an enforced limit. Repayments are retained as separate entries.</div><div class="stats-grid"><div class="stat-card"><div class="stat-top">Sales revenue today <span class="stat-icon">?</span></div><div class="stat-value">${currency.format(sales)}</div><div class="stat-foot">Value of recorded POS sales</div></div><div class="stat-card"><div class="stat-top">Collections today <span class="stat-icon">?</span></div><div class="stat-value">${currency.format(collections)}</div><div class="stat-foot">Cash and electronic receipts</div></div><div class="stat-card"><div class="stat-top">Credit sales today <span class="stat-icon">?</span></div><div class="stat-value">${currency.format(credit)}</div><div class="stat-foot">New customer receivables</div></div><div class="stat-card"><div class="stat-top">Expenses today <span class="stat-icon">?</span></div><div class="stat-value">${currency.format(expenses)}</div><div class="stat-foot">Recorded operating expenses</div></div></div><section class="panel table-panel"><div class="panel-head"><div><h2>Customer credit accounts</h2><p>Outstanding balances, limits and available credit</p></div><button class="button secondary" data-action="new-customer">+ Add credit customer</button></div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Contact</th><th>Credit limit</th><th>Outstanding</th><th>Available</th><th></th></tr></thead><tbody>${customers}</tbody></table></div></section><section class="panel table-panel" style="margin-top:15px"><div class="panel-head"><div><h2>Customer repayments</h2><p>Payments reduce receivables and remain in the repayment register.</p></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Customer</th><th>Method</th><th>Reference</th><th>Amount</th></tr></thead><tbody>${repayments}</tbody></table></div></section><section class="panel table-panel" style="margin-top:15px"><div class="panel-head"><div><h2>Operating expenses</h2><p>Expense records entered by the finance team</p></div><button class="button secondary" data-action="export-expenses">Export CSV</button></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Description</th><th>Category</th><th>Status</th><th>Amount</th></tr></thead><tbody>${rows}</tbody></table></div></section>`}
function renderReports(){const rows=reportSales(),products=state.fuel.map(f=>{const fuelSales=rows.filter(s=>s.fuel===f.id),litres=fuelSales.reduce((a,s)=>a+s.litres,0),rev=totalSales(fuelSales);return `<tr><td class="primary-cell">${fuelName(f.id)}</td><td>${number.format(litres)} L</td><td>${currency.format(rev)}</td><td>${number.format(f.stock)} L</td><td>${number.format(f.capacity)} L</td></tr>`}).join(''),payments=['Cash','Bank card','Mobile money','Bank transfer','Customer credit'].map(m=>`<div class="setting-line"><span>${m}</span><b>${currency.format(totalSales(rows.filter(s=>s.method===m)))}</b></div>`).join(''),deliveryCount=state.deliveries.filter(d=>d.status==='Approved'&&d.date===reportDate).length,shiftCount=state.shifts.filter(s=>s.status==='Closed'&&s.date===reportDate).length;return `${header('Reports','Station activity by product, payment method and operational control.') }<div class="filter-row"><label class="eyebrow" for="report-date">REPORT DATE</label><input type="date" id="report-date" value="${reportDate}"><span class="filter-spacer"></span><button class="button secondary" data-action="export-report">Export report CSV</button></div><div class="stats-grid"><div class="stat-card"><div class="stat-top">Sales value <span class="stat-icon">?</span></div><div class="stat-value">${currency.format(totalSales(rows))}</div><div class="stat-foot">${reportDate} ? POS sales</div></div><div class="stat-card"><div class="stat-top">Volume sold <span class="stat-icon">?</span></div><div class="stat-value">${number.format(rows.reduce((a,s)=>a+s.litres,0))} L</div><div class="stat-foot">${reportDate} ? POS records</div></div><div class="stat-card"><div class="stat-top">Deliveries approved <span class="stat-icon">?</span></div><div class="stat-value">${deliveryCount}</div><div class="stat-foot">${reportDate}</div></div><div class="stat-card"><div class="stat-top">Shifts closed <span class="stat-icon">?</span></div><div class="stat-value">${shiftCount}</div><div class="stat-foot">${reportDate}</div></div></div><div class="two-panels"><section class="panel table-panel"><div class="panel-head"><div><h2>Daily sales and stock</h2><p>Product totals for ${reportDate}</p></div></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Sold</th><th>Sales</th><th>Calculated stock</th><th>Tank capacity</th></tr></thead><tbody>${products}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>Collections by method</h2><p>POS tender split for ${reportDate}</p></div></div>${payments}</section></div><section class="panel table-panel" style="margin-top:15px"><div class="panel-head"><div><h2>Operational activity</h2><p>Deliveries, pump assignments and control records</p></div></div><div class="table-wrap"><table><thead><tr><th>Report</th><th>Records</th><th>Current status</th><th>Review needed</th></tr></thead><tbody><tr><td>Supplier deliveries</td><td>${state.deliveries.length}</td><td>${state.deliveries.filter(d=>d.status==='Pending').length} pending</td><td>${state.deliveries.some(d=>d.status==='Pending')?'Yes':'No'}</td></tr><tr><td>Pump shifts</td><td>${state.shifts.length}</td><td>${state.shifts.filter(s=>s.status==='Open').length} open</td><td>${state.shifts.some(s=>s.status==='Pending review')?'Yes':'No'}</td></tr><tr><td>Physical stock measurements</td><td>${state.measurements.length}</td><td>${state.measurements.filter(m=>Math.abs(m.variance)>state.settings.tolerance).length} outside tolerance</td><td>${state.measurements.some(m=>Math.abs(m.variance)>state.settings.tolerance)?'Yes':'No'}</td></tr></tbody></table></div></section>`}
function renderSettings(){return `${header('Station settings','Configure station identity, stock controls and operating assumptions.') }<div class="section-note"><strong>System roles in the workflow:</strong> Administrator manages accounts and permissions; Manager approves deliveries, adjustments and shift closures; Supervisor records readings and assigns shifts; Cashier records POS transactions; Attendant operates assigned pumps; Accountant records expenses and financial activity.</div><div class="settings-grid"><section class="panel"><div class="panel-head"><div><h2>Station profile</h2><p>Single station configuration</p></div></div><div class="setting-line"><span>Station name</span><b>${esc(state.settings.station)}</b></div><div class="setting-line"><span>Reporting currency</span><b>${esc(state.settings.currency)}</b></div><div class="setting-line"><span>Products</span><b>${state.fuel.length} active</b></div><div class="setting-line"><span>Supplier records</span><b>${state.suppliers.length}</b></div></section><section class="panel"><div class="panel-head"><div><h2>Operational controls</h2><p>Review thresholds and recordkeeping</p></div></div><div class="setting-line"><span>Tank variance tolerance</span><b>${number.format(state.settings.tolerance)} L</b></div><div class="setting-line"><span>Delivery posting</span><b>Manager approval required</b></div><div class="setting-line"><span>Shift closure</span><b>Readings and review required</b></div><div class="setting-line"><span>Transaction correction</span><b>Reversal or adjustment record</b></div></section><section class="panel"><div class="panel-head"><div><h2>Data and access</h2><p>Prototype operating mode</p></div></div><div class="notice-card" style="margin:0">This build saves to this browser’s local storage. It does not provide backend authentication, server-enforced roles, multi-user synchronization, backups or production audit guarantees. Do not use it as the station’s authoritative financial or inventory record yet.</div><div style="margin-top:14px"><button class="button secondary" data-action="reset-data">Reset prototype data</button></div></section><section class="panel"><div class="panel-head"><div><h2>Workflow audit trail</h2><p>Recent actions in this browser</p></div></div><div class="activity-list">${state.audit.slice(0,6).map(a=>`<div class="activity"><span class="activity-dot">${a.icon}</span><div><p>${esc(a.text)}</p><small>${esc(a.time)}</small></div></div>`).join('')}</div></section></div>`}
const renderers={dashboard:renderDashboard,sales:renderSales,deliveries:renderDeliveries,inventory:renderInventory,shifts:renderShifts,reconciliation:renderReconciliation,finance:renderFinance,reports:renderReports,settings:renderSettings};
function settingsManagement(){const backupControl=currentUser.role==='System Administrator'?'<section class="panel" style="margin-top:15px"><div class="panel-head"><div><h2>Database backup</h2><p>Download a consistent SQLite snapshot of station records.</p></div><a class="button secondary" href="/api/backup">Download backup</a></div></section>':'';const fuelRows=state.fuel.map(f=>`<tr><td class="primary-cell">${esc(f.name)}</td><td>${currency.format(f.price)} / L</td><td>${number.format(f.stock)} / ${number.format(f.capacity)} L</td><td><button class="inline-action" data-action="edit-fuel" data-id="${f.id}">Edit product</button></td></tr>`).join('');const suppliers=state.suppliers.map(x=>`<span class="status approved">${esc(x)}</span>`).join(' ');return `<section class="panel"><div class="panel-head"><div><h2>Station configuration</h2><p>Station identity, currency, and variance threshold</p></div><button class="button secondary" data-action="edit-station">Edit settings</button></div></section><section class="panel table-panel" style="margin-top:15px"><div class="panel-head"><div><h2>Fuel products and prices</h2><p>Price changes affect new sales; previous transactions keep their saved price.</p></div></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Selling price</th><th>Calculated / capacity</th><th></th></tr></thead><tbody>${fuelRows}</tbody></table></div></section><section class="panel" style="margin-top:15px"><div class="panel-head"><div><h2>Suppliers</h2><p>Configured delivery suppliers</p></div><button class="button secondary" data-action="add-supplier">+ Add supplier</button></div><div style="display:flex;gap:7px;flex-wrap:wrap">${suppliers}</div></section>${backupControl}${currentUser.role==='System Administrator'?`<section class="panel table-panel" style="margin-top:15px"><div class="panel-head"><div><h2>User accounts</h2><p>Access is enforced on the server for every protected action.</p></div><button class="button primary" data-action="new-user">+ Add user</button></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody>${(state.users||[]).map(u=>`<tr><td class="primary-cell">${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(u.role)}</td><td>${status(u.active?'Active':'Inactive')}</td><td>${u.id===currentUser.id?'Current account':`<button class="inline-action" data-action="toggle-user" data-id="${u.id}" data-active="${u.active?'0':'1'}">${u.active?'Deactivate':'Activate'}</button>`}</td></tr>`).join('')}</tbody></table></div></section>`:''}`}
const viewRoles={dashboard:['System Administrator','Station Manager','Supervisor','Cashier','Fuel Attendant','Accountant'],sales:['System Administrator','Station Manager','Cashier'],deliveries:['System Administrator','Station Manager','Supervisor'],inventory:['System Administrator','Station Manager','Supervisor','Fuel Attendant'],shifts:['System Administrator','Station Manager','Supervisor','Fuel Attendant'],reconciliation:['System Administrator','Station Manager','Supervisor'],finance:['System Administrator','Station Manager','Accountant'],reports:['System Administrator','Station Manager','Supervisor','Accountant'],settings:['System Administrator','Station Manager']};
function render(){if(!state)return;$('#current-section').textContent=views[currentView];$('#page-content').innerHTML=renderers[currentView]();if(currentView==='settings'){const old=Array.from(document.querySelectorAll('#page-content .panel')).find(p=>p.querySelector('h2')?.textContent==='Data and access');old?.remove();$('#page-content').insertAdjacentHTML('beforeend',settingsManagement())}$('#delivery-badge').style.display=state.deliveries.some(d=>d.status==='Pending')?'block':'none';document.querySelectorAll('.nav-item[data-view]').forEach(b=>{const roles=viewRoles[b.dataset.view]||[];b.hidden=!roles.includes(currentUser.role);b.classList.toggle('active',b.dataset.view===currentView)});}
function notify(msg){const t=$('#toast');t.textContent=msg;t.classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.classList.remove('visible'),2500)}
async function api(path,options={}){const response=await fetch(path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})},credentials:'same-origin'});let data={};try{data=await response.json()}catch{}if(!response.ok)throw new Error(data.error||'The request could not be completed.');return data}
function acceptState(next){state=next;currentUser=next.me;currencyCode=next.settings.currency||'USD';const initials=currentUser.name.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();$('#side-name').textContent=currentUser.name;$('#side-role').textContent=currentUser.role;$('#side-avatar').textContent=initials;$('#top-avatar').textContent=initials;$('#station-crumb').textContent=next.settings.station;$('#auth-screen').hidden=true;render()}
function showAuth(setup=false,error=''){const screen=$('#auth-screen');screen.hidden=false;$('#auth-title').textContent=setup?'Create station administrator':'Sign in';$('#auth-eyebrow').textContent=setup?'INITIAL SETUP':'STATION MANAGEMENT';$('#auth-copy').textContent=setup?'Create the first administrator account to configure your station.':'Use your station account to continue.';$('#auth-submit').textContent=setup?'Create administrator':'Sign in';$('#auth-error').textContent=error;$('#auth-fields').innerHTML=`<div class="form-field"><label>Email address</label><input name="email" type="email" autocomplete="username" required></div>${setup?'<div class="form-field"><label>Full name</label><input name="name" autocomplete="name" required></div>':''}<div class="form-field"><label>Password ${setup?'<span class="form-hint">At least 12 characters</span>':''}</label><input name="password" type="password" autocomplete="${setup?'new-password':'current-password'}" minlength="${setup?12:1}" required></div>`;$('#auth-form').onsubmit=async e=>{e.preventDefault();const fields=Object.fromEntries(new FormData(e.target));$('#auth-submit').disabled=true;try{const out=await api(setup?'/api/setup':'/api/login',{method:'POST',body:JSON.stringify(fields)});acceptState(out.state);notify(setup?'Administrator account created. Add staff accounts in Station settings.':'Signed in.')}catch(err){$('#auth-error').textContent=err.message}finally{$('#auth-submit').disabled=false}}}
async function boot(){try{const status=await api('/api/setup-status');if(status.needsSetup){showAuth(true);return}const out=await api('/api/state');acceptState(out.state)}catch(error){if(error.message==='Please sign in to continue.')showAuth(false);else showAuth(false,'Could not connect to the application server. Start it with npm start, then open http://127.0.0.1:3000.')}}
async function postAction(payload){try{const out=await api('/api/action',{method:'POST',body:JSON.stringify(payload)});acceptState(out.state);return true}catch(error){notify(error.message);return false}}
function field(label,name,{type='text',value='',options='',hint='',required=true,step='',min='',readonly=false}={}){const el=type==='select'?`<select name="${name}" ${required?'required':''}>${options}</select>`:type==='textarea'?`<textarea name="${name}" ${required?'required':''}>${esc(value)}</textarea>`:`<input type="${type}" name="${name}" value="${esc(value)}" ${step?`step="${step}"`:''} ${min!==''?`min="${min}"`:''} ${readonly?'readonly':''} ${required?'required':''}>`;return `<div class="form-field"><label>${label}</label>${el}${hint?`<span class="form-hint">${hint}</span>`:''}</div>`}
function openModal(title,content,submitLabel='Save record',onSubmit){$('#modal-title').textContent=title;$('#modal-body').innerHTML=content;$('#modal-submit').textContent=submitLabel;$('#modal-form').onsubmit=async e=>{e.preventDefault();$('#modal-submit').disabled=true;try{if(await onSubmit(new FormData(e.target))!==false){$('#modal').close();render()}}finally{$('#modal-submit').disabled=false}};$('#modal').showModal()}
function newSale(){openModal('Record a sale',`<div class="form-grid">${field('Fuel product','fuel',{type:'select',options:fuelOptions('petrol')})}${field('Pump','pump',{type:'select',options:['Pump 1','Pump 2','Pump 3','Pump 4'].map(x=>`<option>${x}</option>`).join('')})}${field('Quantity in litres','litres',{type:'number',value:'20',step:'0.01',min:'0.01'})}${field('Selling price per litre','price',{type:'number',value:fuelBy('petrol').price,step:'0.01',min:'0.01',readonly:true,hint:'Set in station configuration; saved with the transaction.'})}${field('Payment method','method',{type:'select',options:methodOptions})}${field('Customer or account','customer',{value:'Walk-in',hint:'For Customer credit, enter a registered account name (limit checked automatically).'})}<div class="form-field full"><span class="form-hint">Available stock is checked before saving. The sale reduces calculated stock and remains separate from pump meter readings.</span></div></div>`,'Save sale',d=>postAction({type:'sale',fuel:d.get('fuel'),pump:d.get('pump'),litres:Number(d.get('litres')),price:Number(d.get('price')),method:d.get('method'),customer:d.get('customer')}))}
function newOrder(){openModal('Create purchase order',`<div class="form-grid">${field('Supplier','supplier',{type:'select',options:state.suppliers.map(x=>`<option>${esc(x)}</option>`).join('')})}${field('Fuel product','fuel',{type:'select',options:fuelOptions('petrol')})}${field('Ordered quantity (L)','quantity',{type:'number',step:'0.1',min:'0.1'})}${field('Agreed purchase price per litre','cost',{type:'number',step:'0.0001',min:'0.01'})}${field('Order date','date',{type:'date',value:todayISO()})}${field('Supplier order reference','reference',{required:false})}<div class="form-field full">${field('Order notes','notes',{type:'textarea',required:false})}</div><div class="form-field full"><span class="form-hint">A manager must approve this order before a delivery can be received.</span></div></div>`,'Submit for approval',d=>postAction({type:'purchaseOrder',supplier:d.get('supplier'),fuel:d.get('fuel'),quantity:Number(d.get('quantity')),cost:Number(d.get('cost')),date:d.get('date'),reference:d.get('reference'),notes:d.get('notes')}))}
function reviewOrder(id){const o=state.purchaseOrders.find(x=>x.id===id);openModal('Review purchase order',`<div class="section-note"><strong>${esc(o.supplier)} ? ${fuelName(o.fuel)}</strong><br>${number.format(o.quantity)} L at ${currency.format(o.cost)}/L<br>Submitted by ${esc(o.requestedBy)} ? ${esc(o.reference||'No reference')}</div><div class="form-grid"><div class="form-field full"><label>Review outcome</label><select name="outcome"><option value="Approved">Approve order</option><option value="Rejected">Reject order</option></select></div><div class="form-field full">${field('Review notes (required when rejecting)','note',{type:'textarea',required:false})}</div></div>`,'Save review',d=>postAction({type:'purchaseOrderReview',id,outcome:d.get('outcome'),note:d.get('note')}))}
function newDelivery(){const orders=(state.purchaseOrders||[]).filter(o=>['Approved','Partially received'].includes(o.status)&&(o.quantity-(o.received||0)-state.deliveries.filter(d=>d.orderId===o.id&&d.status==='Pending').reduce((n,d)=>n+d.quantity,0))>0);if(!orders.length){notify('Create and approve a purchase order before recording a delivery.');return}const orderOptions=orders.map(o=>`<option value="${o.id}">${esc(o.id)} ? ${esc(o.supplier)} ? ${fuelName(o.fuel)} ? ${number.format(o.quantity-(o.received||0))} L remaining</option>`).join('');const chosen=orders[0];openModal('Record a fuel delivery',`<div class="form-grid">${field('Approved purchase order','orderId',{type:'select',options:orderOptions})}${field('Supplier','supplier',{type:'select',options:state.suppliers.map(x=>`<option ${x===chosen.supplier?'selected':''}>${esc(x)}</option>`).join('')})}${field('Fuel product','fuel',{type:'select',options:fuelOptions(chosen.fuel)})}${field('Delivered quantity (L)','quantity',{type:'number',step:'0.1',min:'0.1'})}${field('Purchase price per litre','cost',{type:'number',step:'0.0001',min:'0.01',value:chosen.cost})}${field('Delivery date','date',{type:'date',value:todayISO()})}${field('Invoice reference','invoice',{required:false})}<div class="form-field full">${field('Delivery notes','notes',{type:'textarea',required:false})}</div><div class="form-field full"><span class="form-hint">Receipt must match the approved supplier and fuel. Stock changes only after delivery approval.</span></div></div>`,'Save for approval',d=>postAction({type:'delivery',orderId:d.get('orderId'),supplier:d.get('supplier'),fuel:d.get('fuel'),quantity:Number(d.get('quantity')),cost:Number(d.get('cost')),date:d.get('date'),invoice:d.get('invoice'),notes:d.get('notes')}))}
function reviewDelivery(id){const d=state.deliveries.find(x=>x.id===id);openModal('Review delivery',`<div class="section-note"><strong>${esc(d.supplier)} · ${fuelName(d.fuel)}</strong><br>${number.format(d.quantity)} L · Invoice ${esc(d.invoice||'not supplied')} · Recorded ${d.date}<br>Approve only after checking delivered volume and supporting documents.</div><div class="form-grid">${field('Review outcome','outcome',{type:'select',options:'<option value="Approved">Approve and post stock</option><option value="Rejected">Reject delivery</option>'})}${field('Reason or review notes','note',{type:'textarea',required:false})}</div>`,'Save review',f=>postAction({type:'deliveryReview',id,outcome:f.get('outcome'),note:f.get('note')}))}
function newMeasurement(){openModal('Record tank measurement',`<div class="form-grid">${field('Fuel product','fuel',{type:'select',options:fuelOptions('petrol')})}${field('Measured quantity (L)','quantity',{type:'number',step:'0.1',min:'0'})}${field('Date and time','date',{type:'datetime-local',value:new Date().toISOString().slice(0,16)})}<div class="form-field full">${field('Measurement notes','note',{type:'textarea',required:false})}</div><div class="form-field full"><span class="form-hint">This measurement is compared with calculated stock. It does not change stock balances.</span></div></div>`,'Save measurement',d=>postAction({type:'measurement',fuel:d.get('fuel'),quantity:Number(d.get('quantity')),date:d.get('date'),note:d.get('note')}))}
function newAdjustment(){openModal('Request stock adjustment',`<div class="form-grid">${field('Fuel product','fuel',{type:'select',options:fuelOptions('petrol')})}${field('Adjustment amount (L)','quantity',{type:'number',step:'0.1'})}<div class="form-field full">${field('Reason (required)','reason',{type:'textarea'})}</div><div class="form-field full"><span class="form-hint">An adjustment is pending until an authorised manager approves it. The reason and approval are retained.</span></div></div>`,'Submit for approval',d=>postAction({type:'adjustment',fuel:d.get('fuel'),quantity:Number(d.get('quantity')),reason:d.get('reason')}))}
function approveAdjustment(id){const a=state.adjustments.find(x=>x.id===id);openModal('Review stock adjustment',`<div class="section-note"><strong>${fuelName(a.fuel)} · ${a.quantity>0?'+':''}${number.format(a.quantity)} L</strong><br>${esc(a.reason)}<br>Requested by ${esc(a.requestedBy||'station staff')} on ${a.date}.</div><div class="form-grid"><div class="form-field full"><label>Review outcome</label><select name="outcome"><option value="Approved">Approve and post adjustment</option><option value="Rejected">Reject request</option></select></div><div class="form-field full">${field('Review notes (required when rejecting)','note',{type:'textarea',required:false})}</div></div>`,'Save review',d=>{if(d.get('outcome')==='Rejected'&&!d.get('note').trim()){notify('Add a reason before rejecting this adjustment.');return false}return postAction({type:'adjustmentReview',id,outcome:d.get('outcome'),note:d.get('note')})})}
function newShift(){openModal('Open a pump shift',`<div class="form-grid">${field('Attendant','attendant',{value:''})}${field('Pump','pump',{type:'select',options:['Pump 1','Pump 2','Pump 3','Pump 4'].map(x=>`<option>${x}</option>`).join('')})}${field('Fuel product','fuel',{type:'select',options:fuelOptions('petrol')})}${field('Opening meter reading (L)','opening',{type:'number',step:'0.01',min:'0'})}${field('Shift date','date',{type:'date',value:todayISO()})}${field('Opening time','time',{type:'time',value:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})})}</div>`,'Open shift',d=>postAction({type:'shiftOpen',attendant:d.get('attendant'),pump:d.get('pump'),fuel:d.get('fuel'),opening:Number(d.get('opening')),date:d.get('date'),time:d.get('time')}))}
function closeShift(id){const s=state.shifts.find(x=>x.id===id);openModal(`Close ${s.id}`,`<div class="section-note"><strong>${esc(s.attendant)} · ${s.pump} · ${fuelName(s.fuel)}</strong><br>Opening meter ${number.format(s.opening)} L</div><div class="form-grid">${field('Closing meter reading (L)','closing',{type:'number',step:'0.01',min:String(s.opening)})}${field('Closing time','closed',{type:'time',value:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})})}${['Cash','Bank card','Mobile money','Bank transfer','Customer credit'].map((m,i)=>field(`${m} collected`, `pay${i}`,{type:'number',value:'0',step:'0.01',min:'0'})).join('')}<div class="form-field full">${field('Supervisor notes','note',{type:'textarea',required:false})}</div></div><div class="form-hint" style="margin-top:10px">Meter dispensing is compared with POS sales and collections after closing. Keep supporting notes for variances.</div>`,'Submit reconciliation',d=>{const collections=Object.fromEntries(['Cash','Bank card','Mobile money','Bank transfer','Customer credit'].map((m,i)=>[m,Number(d.get(`pay${i}`)||0)]));return postAction({type:'shiftClose',id,closing:Number(d.get('closing')),closed:d.get('closed'),note:d.get('note'),collections})})}
function reviewShift(id){const s=state.shifts.find(x=>x.id===id),price=s.price||fuelBy(s.fuel).price,expected=shiftLitres(s)*price,collected=Object.values(s.collections||{}).reduce((a,x)=>a+Number(x||0),0),pos=totalSales(s.sales||[]),variance=expected-collected;openModal(`Review shift ${s.id}`,`<div class="metric-pair"><div class="metric-box"><small>Expected sales (${number.format(shiftLitres(s))} L × ${currency.format(price)})</small><b>${currency.format(expected)}</b></div><div class="metric-box"><small>POS sales · Collections</small><b>${currency.format(pos)} · ${currency.format(collected)}</b></div></div><div class="section-note">${Math.abs(variance)>1?`<strong>Variance ${currency.format(variance)} requires investigation.</strong>`:'Collections align with expected sales.'} Confirm the reconciliation notes and supporting evidence before closing.</div><div class="form-grid"><div class="form-field full">${field('Manager review notes','note',{type:'textarea',value:s.note||'',required:Math.abs(variance)>1})}</div><div class="form-field full"><label>Review outcome</label><select name="outcome"><option value="Closed">Approve and close shift</option><option value="Pending review">Return for follow-up</option></select></div></div>`,'Save review',d=>postAction({type:'shiftReview',id,note:d.get('note'),outcome:d.get('outcome')}))}
function requestReversal(id){const sale=state.sales.find(x=>x.id===id);openModal('Request sale reversal',`<div class="section-note"><strong>${sale.id} ? ${fuelName(sale.fuel)} ? ${number.format(sale.litres)} L ? ${currency.format(amountOf(sale))}</strong><br>Approved reversals restore fuel stock and remain in the transaction history.</div><div class="form-grid"><div class="form-field full">${field('Reason for reversal (required)','reason',{type:'textarea'})}</div></div>`,'Submit for manager review',d=>postAction({type:'saleReversal',id,reason:d.get('reason')}))}
function reviewSaleReversal(id){const r=state.saleReversals.find(x=>x.id===id),sale=state.sales.find(x=>x.id===r.saleId);openModal('Review sale reversal',`<div class="section-note"><strong>${sale.id}</strong><br>Requested by ${esc(r.requestedBy)} ? ${esc(r.reason)}</div><div class="form-grid"><div class="form-field full"><label>Review outcome</label><select name="outcome"><option value="Approved">Approve reversal</option><option value="Rejected">Reject request</option></select></div><div class="form-field full"><label>Was fuel dispensed?</label><select name="restoreStock"><option value="false">Yes, fuel was dispensed (do not restore stock)</option><option value="true">No, no fuel left the pump (restore stock)</option></select></div><div class="form-field full">${field('Review notes','note',{type:'textarea',required:false})}</div></div>`,'Save review',d=>postAction({type:'saleReversalReview',id,outcome:d.get('outcome'),restoreStock:d.get('restoreStock')==='true',note:d.get('note')}))}
function newCustomer(){openModal('Add credit customer',`<div class="form-grid">${field('Customer or business name','name')}${field('Contact details','contact',{required:false})}${field('Credit limit','creditLimit',{type:'number',step:'0.01',min:'0'})}</div><div class="form-hint">Credit sales are blocked until an account is created and are checked against its outstanding balance and limit.</div>`,'Create account',d=>postAction({type:'customer',name:d.get('name'),contact:d.get('contact'),creditLimit:Number(d.get('creditLimit'))}))}
function repayCustomer(id){const c=state.customers.find(x=>x.id===id),balance=accountBalance(c);openModal('Record customer repayment',`<div class="section-note"><strong>${esc(c.name)}</strong><br>Outstanding balance: ${currency.format(balance)}</div><div class="form-grid">${field('Amount received','amount',{type:'number',step:'0.01',min:'0.01'})}${field('Payment method','method',{type:'select',options:['Cash','Bank card','Mobile money','Bank transfer'].map(x=>`<option>${x}</option>`).join('')})}${field('Payment date','date',{type:'date',value:todayISO()})}${field('Receipt or reference','reference',{required:false})}</div>`,'Save repayment',d=>postAction({type:'repayment',customerId:id,amount:Number(d.get('amount')),method:d.get('method'),date:d.get('date'),reference:d.get('reference')}))}
function newExpense(){openModal('Record an expense',`<div class="form-grid">${field('Description','description')}${field('Category','category',{type:'select',options:['Maintenance','Utilities','Transport','Supplies','Staff','Other'].map(x=>`<option>${x}</option>`).join('')})}${field('Amount','amount',{type:'number',step:'0.01',min:'0.01'})}${field('Date','date',{type:'date',value:todayISO()})}<div class="form-field full">${field('Notes or reference','note',{type:'textarea',required:false})}</div></div>`,'Save expense',d=>postAction({type:'expense',description:d.get('description'),category:d.get('category'),amount:Number(d.get('amount')),date:d.get('date'),note:d.get('note')}))}
function editStation(){const s=state.settings;openModal('Station settings',`<div class="form-grid">${field('Station name','station',{value:s.station})}${field('Currency code','currency',{value:s.currency,hint:'Use a three-letter currency code, for example USD.'})}${field('Tank variance tolerance (L)','tolerance',{type:'number',value:s.tolerance,min:'0',step:'1'})}</div>`,'Save settings',d=>postAction({type:'settings',station:d.get('station'),currency:d.get('currency'),tolerance:Number(d.get('tolerance'))}))}
function editFuel(id){const f=fuelBy(id);openModal(`Edit ${f.name}`,`<div class="form-grid">${field('Product name','name',{value:f.name})}${field('Selling price per litre','price',{type:'number',value:f.price,min:'0.01',step:'0.01'})}${field('Tank capacity (L)','capacity',{type:'number',value:f.capacity,min:'1',step:'1'})}<div class="form-field full"><span class="form-hint">Current calculated stock: ${number.format(f.stock)} L. Price changes apply to future POS sales only.</span></div></div>`,'Save product',d=>postAction({type:'fuelUpdate',id,name:d.get('name'),price:Number(d.get('price')),capacity:Number(d.get('capacity')),color:f.color}))}
function addSupplier(){openModal('Add supplier',`<div class="form-grid">${field('Supplier name','name')}</div>`,'Add supplier',d=>postAction({type:'supplier',name:d.get('name')}))}
function createUser(){openModal('Create user account',`<div class="form-grid">${field('Full name','name')}${field('Email address','email',{type:'email'})}${field('Role','role',{type:'select',options:['System Administrator','Station Manager','Supervisor','Cashier','Fuel Attendant','Accountant'].map(x=>`<option>${x}</option>`).join('')})}${field('Temporary password','password',{type:'password',hint:'At least 12 characters.'})}</div>`,'Create account',d=>postAction({type:'user',name:d.get('name'),email:d.get('email'),role:d.get('role'),password:d.get('password')}))}
function toggleUser(id,active){return postAction({type:'userStatus',id,active:active==='1'})}
function csvDownload(name,rows){const csv=rows.map(row=>row.map(x=>`"${String(x??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download=name;a.click();URL.revokeObjectURL(a.href);notify('CSV export downloaded.')}
function exportSales(){csvDownload(`mututsva-sales-${todayISO()}.csv`,[['Transaction','Date','Time','Product','Litres','Unit price','Pump','Payment method','Customer','Total','Status'],...state.sales.map(s=>[s.id,s.date,s.time,fuelName(s.fuel),s.litres,s.price,s.pump,s.method,s.customer,amountOf(s).toFixed(2),s.reversedAt?'Reversed':'Recorded'])])}
function exportExpenses(){csvDownload(`mututsva-expenses-${todayISO()}.csv`,[['Date','Description','Category','Amount','Status'],...state.expenses.map(e=>[e.date,e.description,e.category,e.amount,e.status])])}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){currentView=nav.dataset.view;render();return}const action=e.target.closest('[data-action]');if(!action)return;const {action:act,id}=action.dataset;({ 'new-sale':newSale,'new-delivery':newDelivery,'new-order':newOrder,'review-order':()=>reviewOrder(id),'new-measurement':newMeasurement,'new-adjustment':newAdjustment,'new-shift':newShift,'new-expense':newExpense,'new-customer':newCustomer,'repay-customer':()=>repayCustomer(id),'request-reversal':()=>requestReversal(id),'review-reversal':()=>reviewSaleReversal(id),'export-sales':exportSales,'export-expenses':exportExpenses,'approve-delivery':()=>reviewDelivery(id),'close-shift':()=>closeShift(id),'review-shift':()=>reviewShift(id),'approve-adjustment':()=>approveAdjustment(id),'export-report':()=>csvDownload(`mututsva-report-${reportDate}.csv`,[['Product','Litres sold','Sales','Calculated stock'],...state.fuel.map(f=>[f.name,reportSales().filter(s=>s.fuel===f.id).reduce((a,s)=>a+s.litres,0),totalSales(reportSales().filter(s=>s.fuel===f.id)),f.stock])]),'reset-data':()=>{if(confirm('Reset this browser prototype to its sample data?')){state=initialState();render();notify('Prototype data reset.')}}})[act]?.()});
document.addEventListener('input',e=>{if(e.target.id==='sales-search'||e.target.id==='sales-filter'){const q=$('#sales-search').value.toLowerCase(),m=$('#sales-filter').value;const rows=state.sales.filter(s=>(!m||s.method===m)&&(!q||`${s.id} ${s.pump} ${s.customer}`.toLowerCase().includes(q))).map(s=>`<tr><td><div class="primary-cell">${s.id}</div><div class="secondary-cell">${s.date} · ${s.time}</div></td><td>${fuelName(s.fuel)}</td><td>${number.format(s.litres)} L</td><td>${currency.format(s.price)}/L</td><td>${s.pump}</td><td>${s.method}</td><td class="primary-cell">${currency.format(amountOf(s))}</td><td>${s.reversedAt?status('Reversed'):state.saleReversals?.some(r=>r.saleId===s.id&&r.status==='Pending')?status('Pending review'):`<button class="inline-action" data-action="request-reversal" data-id="${s.id}">Request reversal</button>`}</td></tr>`).join('')||'<tr><td colspan="8" class="empty-state">No matching transactions.</td></tr>';$('#sales-body').innerHTML=rows}});
document.addEventListener('change',e=>{if(e.target.id==='report-date'){reportDate=e.target.value||todayISO();render();return}if(e.target.name==='fuel'&&$('#modal').open){const f=fuelBy(e.target.value),price=$('#modal-body [name="price"]');if(price)price.value=f.price}});
$('#navigation').addEventListener('click',()=>{});$('#today').textContent=new Date().toLocaleDateString('en',{weekday:'short',month:'short',day:'numeric',year:'numeric'});$('#help-button').addEventListener('click',()=>notify('Mututsva FSMS · station workflow prototype'));render();

document.addEventListener('click',async e=>{const action=e.target.closest('[data-action]');if(action){const {action:act,id}=action.dataset;if(act==='edit-station')editStation();else if(act==='edit-fuel')editFuel(id);else if(act==='add-supplier')addSupplier();else if(act==='new-user')createUser();else if(act==='toggle-user')toggleUser(id,action.dataset.active);return}if(e.target.closest('#user-menu')){try{await api('/api/logout',{method:'POST',body:'{}'})}catch{}state=null;currentUser=null;currentView='dashboard';showAuth(false)}});
boot();
